mapper.select:
SELECT 
FROM tbl_eps_budget_import_log
WHERE deleted = 0 AND created_by = #{createdBy}

    AND created_time >= #{startDate}


    AND created_time <= #{endDate}

ORDER BY created_time DESC

SELECT import_status as status, COUNT(1) as count, SUM(total_records) as total_records, SUM(success_records) as success_records, SUM(failed_records) as failed_records FROM tbl_eps_budget_import_log WHERE deleted = 0
AND system_id = #{systemId}
AND version_id = #{versionId}
AND created_time >= #{startDate}
AND created_time <= #{endDate}
GROUP BY import_status ORDER BY count DESC

SELECT DATE(created_time) as import_date, COUNT(1) as count, SUM(total_records) as total_records, SUM(success_records) as success_records, SUM(failed_records) as failed_records FROM tbl_eps_budget_import_log WHERE deleted = 0
AND system_id = #{systemId}
AND version_id = #{versionId}
AND created_time >= #{startDate}
AND created_time <= #{endDate}
GROUP BY DATE(created_time) ORDER BY import_date DESC

SELECT COUNT(1) as total_imports, AVG(import_duration) as avg_duration, MIN(import_duration) as min_duration, MAX(import_duration) as max_duration, SUM(CASE WHEN import_duration <= 60 THEN 1 ELSE 0 END) as fast_imports, SUM(CASE WHEN import_duration > 60 AND import_duration <= 300 THEN 1 ELSE 0 END) as medium_imports, SUM(CASE WHEN import_duration > 300 THEN 1 ELSE 0 END) as slow_imports FROM tbl_eps_budget_import_log WHERE deleted = 0 AND import_status = 'COMPLETED' AND import_duration IS NOT NULL
AND system_id = #{systemId}
AND version_id = #{versionId}
AND created_time >= #{startDate}
AND created_time <= #{endDate}

SELECT template_id, COUNT(1) as usage_count, SUM(total_records) as total_records, SUM(success_records) as success_records, SUM(failed_records) as failed_records, AVG(import_duration) as avg_duration FROM tbl_eps_budget_import_log WHERE deleted = 0 AND template_id IS NOT NULL
AND created_time >= #{startDate}
AND created_time <= #{endDate}
GROUP BY template_id ORDER BY usage_count DESC
